#!/bin/bash

# Rapid Construct Massive
#
# (c) IjorTengab <ijortengab@systemix.id> <ijortengab@gmail.com>
#
# https://github.com/ijortengab/rcm
#
# Command to download: `wget git.io/rcm`
#

# Common Functions.
RCM_VERSION='0.18.0-alpha.6'

source /usr/local/rcm/$RCM_VERSION/functions/common/echo.sh

# Parse arguments. Generated by parse-options.sh
_new_arguments=()
_n=
while [[ $# -gt 0 ]]; do
    case "$1" in
        --help|-h) help=1; shift ;;
        --version|-V) version=1; shift ;;
        --interactive) interactive=1; shift ;;
        --no-confirmation) confirmation=0; shift ;;
        --non-interactive|-x) interactive=0; shift ;;
        --no-timer) timer=0; shift ;;
        --slow|-s) fast=0; shift ;;
        --verbose|-v) verbose="$((verbose+1))"; shift ;;
        -[^-]*) _new_arguments+=("$1"); shift ;;
        --)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        --[^-]*) shift ;;
        *)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
    esac
done
set -- "${_new_arguments[@]}"
_new_arguments=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        -[^-]*) OPTIND=1
            while getopts ":hVxsv" opt; do
                case $opt in
                    h) help=1 ;;
                    V) version=1 ;;
                    x) interactive=0 ;;
                    s) fast=0 ;;
                    v) verbose="$((verbose+1))" ;;
                esac
            done
            _n="$((OPTIND-1))"
            _n=${!_n}
            shift "$((OPTIND-1))"
            if [[ "$_n" == '--' ]];then
                while [[ $# -gt 0 ]]; do
                    case "$1" in
                        *) _new_arguments+=("$1"); shift ;;
                    esac
                done
            fi
            ;;
        --) shift
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
        *)
            while [[ $# -gt 0 ]]; do
                case "$1" in
                    *) _new_arguments+=("$1"); shift ;;
                esac
            done
            ;;
    esac
done
set -- "${_new_arguments[@]}"
unset _new_arguments
unset _n

# If not set in argument, try load from environment.
[ -z "$fast" ] && fast="$RCM_FAST"
[ -z "$verbose" ] && verbose="$RCM_VERBOSE"
[ -z "$interactive" ] && interactive="$RCM_INTERACTIVE"

# If set in environment, set to variable.
[ -n "$RCM_LOG" ] && log="$RCM_LOG"

# Boolean default to TRUE.
[ -z "$confirmation" ] && confirmation=1; [ "$confirmation" == 0 ] && confirmation=
[ -z "$timer" ] && timer=1; [ "$timer" == 0 ] && timer=
[ -z "$fast" ] && fast=1; [ "$fast" == 0 ] && fast=
[ -z "$interactive" ] && interactive=1; [ "$interactive" == 0 ] && interactive=

# Verbosity.
quiet=; loud=; louder=; debug=;
[[ -z "$verbose" || "$verbose" -lt 1 ]] && quiet=1 || quiet=
[[ "$verbose" -gt 0 ]] && loud=1
[[ "$verbose" -gt 1 ]] && loud=1 && louder=1
[[ "$verbose" -gt 2 ]] && loud=1 && louder=1 && debug=1

# Define variables and constants.
RCM_DELAY=${RCM_DELAY:=.5}; [ -n "$fast" ] && unset RCM_DELAY
RCM_INDENT='    '; [ "$(tput cols)" -le 80 ] && RCM_INDENT='  '
[ -z "$log" ] && log=rcm.log
tempfile=

# Functions. Help and Version.
printHelp() {
    title Rapid Construct Massive
    _ 'Version '; yellow $RCM_VERSION; _.
    _ 'URL '; yellow git.io/rcm; _.
    _.
cat << EOF
Usage: rcm [options]
       rcm <extension> [options]
       rcm [options] <extension> [options]

Global Options:
   --version
        Print version of this script.
   --help
        Show this help.
   --slow, -s
        Add delay every subtask.
   --interactive
        Show asking for confirmation if needed. Default action.
   --non-interactive, -x
        Run without ever asking for user input.
   --verbose, -v
        Verbose mode. Causes rcm to print debugging messages about its progress.
        Multiple -v options increase the verbosity.
        The maximum is 3.
EOF
}

# Help and Version.
[ -n "$help" ] && { printHelp; exit 1; }
[ -n "$version" ] && { echo $RCM_VERSION; exit 1; }

if [ -z "$1" ];then
    printHelp >/dev/null | head -3
    _ Try; blue ' 'rcm; magenta ' '--help; _, ' 'for more information.; _.
    exit 0
fi

extension="$1"; shift
command="rcm-${extension}"

# Title.
title rcm
____

[ -n "$debug" ] && chapter Dump variable.
[ -n "$debug" ] && code 'RCM_INTERACTIVE="'$RCM_INTERACTIVE'"'
[ -n "$debug" ] && code 'RCM_VERBOSE="'$RCM_VERBOSE'"'
[ -n "$debug" ] && code 'RCM_FAST="'$RCM_FAST'"'
[ -n "$debug" ] && code 'RCM_LOG="'$RCM_LOG'"'
[ -n "$debug" ] && code 'RCM_VERSION="'$RCM_VERSION'"'
[ -n "$debug" ] && code 'interactive="'$interactive'"'
[ -n "$debug" ] && code 'verbose="'$verbose'"'
[ -n "$debug" ] && code 'quiet="'$quiet'"'
[ -n "$debug" ] && code 'loud="'$loud'"'
[ -n "$debug" ] && code 'louder="'$louder'"'
[ -n "$debug" ] && code 'debug="'$debug'"'
[ -n "$debug" ] && code 'log="'$log'"'
[ -n "$debug" ] && ____

source /usr/local/rcm/$RCM_VERSION/rcm-exec.sh

exit 0

